-- Credit Score Trend — a monthly credit-score tracker, shown on the
-- Dashboard's Finance life area. Mike has a recurring reminder on the 22nd
-- of each month to check his score across several sources; historically he
-- tracked CreditKarma, CreditSesame, Discover/Fico, and CreditWise in a
-- Google Sheet, but CreditSesame and Discover/Fico are deprecated sources
-- he no longer checks — only CreditKarma and CreditWise get entered going
-- forward (see POST /api/credit-score in index.ts). All four columns stay
-- on the table (nullable) so the 15+ years of historical rows imported
-- below keep their real per-source values — a row's average is computed
-- from whichever of the four columns are non-null (2 for every new row
-- from here on, up to 4 for old ones), not stored, so nothing needs
-- recalculating if that definition ever changes.
--
-- Keyed by entry_date (the exact day recorded, historically always the
-- 22nd) rather than by month, but the app's add/update logic treats "one
-- entry per calendar month" as the real invariant — see POST
-- /api/credit-score's upsert-by-month comment in index.ts.
CREATE TABLE IF NOT EXISTS credit_score_entries (
  entry_date TEXT PRIMARY KEY, -- YYYY-MM-DD
  creditkarma REAL,
  creditsesame REAL,  -- historical only — deprecated source, not entered going forward
  discover_fico REAL, -- historical only — deprecated source, not entered going forward
  creditwise REAL,
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL
);

CREATE INDEX IF NOT EXISTS idx_credit_score_entries_date ON credit_score_entries (entry_date);

-- Historical data imported from Mike's Google Sheet export ("Credit Score
-- Trend.xlsx", "Monthly Credit Score" tab) — 187 monthly readings, one per
-- month with no gaps, from 2011-03-22 through 2026-09-22. A '-' cell in the
-- source sheet (a source not yet tracked yet, or already carrying a stale
-- frozen value by the time it was dropped) imports as NULL here.
ON CONFLICT (entry_date) DO NOTHING;
